package com.dao;import java.sql.*;import java.util.*;import com.entity.Doctor;import com.util.PasswordUtil;public class DoctorDao{private Connection c;public DoctorDao(Connection c){this.c=c;}private Doctor m(ResultSet r)throws Exception{Doctor d=new Doctor();d.setId(r.getInt("id"));d.setFullName(r.getString("full_name"));d.setQualification(r.getString("qualification"));d.setSpecialist(r.getString("specialist"));d.setEmail(r.getString("email"));d.setPhone(r.getString("phone"));return d;}public Doctor login(String e,String pw){try(PreparedStatement p=c.prepareStatement("SELECT * FROM doctors WHERE email=?")){p.setString(1,e);ResultSet r=p.executeQuery();if(r.next()&&PasswordUtil.matches(pw,r.getString("password_hash")))return m(r);}catch(Exception x){x.printStackTrace();}return null;}public boolean add(Doctor d){try(PreparedStatement p=c.prepareStatement("INSERT INTO doctors(full_name,qualification,specialist,email,phone,password_hash) VALUES(?,?,?,?,?,?)")){p.setString(1,d.getFullName());p.setString(2,d.getQualification());p.setString(3,d.getSpecialist());p.setString(4,d.getEmail());p.setString(5,d.getPhone());p.setString(6,PasswordUtil.hash(d.getPassword()));return p.executeUpdate()==1;}catch(Exception x){x.printStackTrace();return false;}}public List<Doctor> all(){List<Doctor> a=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM doctors ORDER BY full_name")){while(r.next())a.add(m(r));}catch(Exception x){x.printStackTrace();}return a;}}